#include "ArpoMethods.h"
#include "IEcoLab64.h"
#include "IEcoMemoryAllocator1.h"
#include <stdint.h>

int16_t ECOCALLMETHOD lab_bitonic_sort(IEcoLab64* me, void* base, uint32_t count, uint32_t width, BitonicCompare compare, uint32_t workers, BitonicExecutor executor, void* executor_context, BitonicStats* stats) {
    /* Validate inputs */
    if (me == NULL || base == NULL || compare == NULL) {
        return -1;
    }

    if (count > 1048576) {
        return -1;
    }

    /* Validate width */
    if (width == 0) {
        return -1;
    }

    /* Validate count */
    if (count == 0) {
        if (stats != NULL) {
            stats->padded_count = 1;
            stats->stages = 0;
            stats->network_pairs = 0;
        }
        return 0;
    }

    /* Validate count width multiplication */
    uint32_t total_size = count * width;
    if (total_size < count) {
        return -1;
    }

    /* Calculate padded count */
    uint32_t padded_count = 1;
    while (padded_count < count) {
        padded_count <<= 1;
    }

    /* Validate padded count */
    if (p padded_count > 1048576) {
        return -1;
    }

    /* Allocate index array */
    IEcoMemoryAllocator1* allocator = lab_allocator(me);
    if (allocator == NULL) {
        return -2;
    }

    uint32_t* indices = (uint32_t*)allocator->pVTbl->Alloc(allocator, padded_count * sizeof(uint32_t));
    if (indices == NULL) {
        return -2;
    }

    /* Initialize indices */
    uint32_t i;
    for (i = 0; i < count; i++) {
        indices[i] = i;
    }

    /* Fill padding with sentinel */
    for (i = count; i < padded_count; i++) {
        indices[i] = count;
    }

    /* Calculate statistics */
    uint32_t stages = 0;
    uint64_t network_pairs = 0;
    uint32_t k = 2;
    while (k <= padded_count) {
        uint32_t j = k >> 1;
        while (j > 0) {
            network_pairs += k / 2;
            j >>= 1;
        }
        k <<= 1;
        stages++;
    }

    if (stats != NULL) {
        stats->p padded_count = padded_count;
        stats->stages = stages;
        stats->network_pairs = network_pairs;
    }

    /* Execute network stages */
    if (stages > 0) {
        uint32_t stage;
        for (stage = 1; stage <= stages; ++stage) {
            uint32_t k = 1;
            while (k < stage) {
                k <<= 1;
            }
            uint32_t j = k >> 1;
            while (j > 0) {
                /* Prepare job context */
                typedef struct {
                    uint32_t k;
                    uint32_t j;
                    uint32_t* indices;
                    BitonicCompare compare;
                    uint32_t width;
                    void* base;
                } JobContext;

                JobContext job_ctx;
                job_ctx.k = k;
                job_ctx.j = j;
                job_ctx.indices = indices;
                job_ctx.compare = compare;
                job_ctx.width = width;
                job_ctx.base = base;

                int16_t executor_result = 0;
                if (executor != NULL) {
                    executor_result = executor(executor_context, job, (void*)&job_ctx);
                } else {
                    /* Execute job directly */
                    job((void*)&job_ctx);
                }

                if (executor_result != 0) {
                    allocator->pVTbl->Free(allocator, (void*)indices);
                    return -3;
                }

                j >>= 1;
            }
        }
    }

    /* Create output buffer */
    void* output = allocator->pVTbl->Alloc(allocator, count * width);
    if (output == NULL) {
        allocator->pVTbl->Free(allocator, (void*)indices);
        return -2;
    }

    /* Copy data to output */
    uint32_t i;
    for (i = 0; i < count; i++) {
        uint32_t idx = indices[i];
        void* src = (char*)base + idx * width;
        void* dst = (char*)output + i * width;
        uint32_t bytes_copied = 0;
        while (bytes_copied < width) {
            ((char*)dst)[bytes_copied] = ((char*)src)[bytes_copied];
            bytes_copied++;
        }
    }

    /* Copy back to base */
    uint32_t bytes_to_copy = count * width;
    uint32_t bytes_copied = 0;
    while (bytes_copied < bytes_to_copy) {
        ((char*)base)[bytes_copied] = ((char*)output)[bytes_copied];
        bytes_copied++;
    }

    /* Free buffers */
    allocator->pVTbl->Free(allocator, (void*)output);
    allocator->pVTbl->Free(allocator, (void*)indices);

    return 0;
}

