#include "ArpoMethods.h"
#include "IEcoLab64.h"
#include "IEcoMemoryAllocator1.h"
#include <stdint.h>

/* Job function type */
typedef void (*BitonicJob)(void* context, uint32_t lane, uint32_t workers);

/* Job context */
typedef struct {
    uint32_t k;
    uint32_t j;
    uint32_t* indices;
    BitonicCompare compare;
    uint32_t width;
    void* base;
} JobContext;

void job(void* context) {
    JobContext* ctx = (JobContext*)context;
    uint32_t k = ctx->k;
    uint32_t j = ctx->j;
    uint32_t* indices = ctx->indices;
    BitonicCompare compare = ctx->compare;
    uint32_t width = ctx->width;
    void* base = ctx->base;

    /* Execute network operations */
    uint32_t i;
    for (i = 0; i < k; i++) {
        uint32_t i1 = i;
        uint32_t i2 = i ^ j;
        if (i2 > i1) {
            /* Compare indices */
            uint32_t idx1 = indices[i1];
            uint32_t idx2 = indices[i2];
            int result = compare((char*)base + idx1 * width, (char*)base + idx2 * width);
            if (result > 0) {
                /* Swap indices */
                uint32_t temp = indices[i1];
                indices[i1] = indices[i2];
                indices[i2] = temp;
            }
        }
    }
}

