#include "ArpoMethods.h"
#include "IEcoLab64.h"
#include "IEcoMemoryAllocator1.h"
#include <stdint.h>

static void ECOCALLMETHOD stage_job(void* context, uint32_t lane, uint32_t workers) {
    struct {
        uint32_t* indices;
        uint32_t* base;
        uint32_t width;
        uint32_t count;
        BitonicCompare compare;
        uint32_t k;
        uint32_t j;
    } *ctx = (struct *)context;

    uint32_t i = lane;
    while (i < ctx->count) {
        uint32_t partner = i ^ ctx->j;
        if (partner > i) {
            uint32_t idx1 = ctx->indices[i];
            uint32_t idx2 = ctx->indices[partner];
            int ascending = (i & ctx->k) == 0;
            int compare_result = ctx->compare((char*)ctx->base + idx1 * ctx->width,
                                               (char*)ctx->base + idx2 * ctx->width);
            if ((ascending && compare_result > 0) || (!ascending && compare_result < 0)) {
                ctx->indices[i] = idx2;
                ctx->indices[partner] = idx1;
            }
        }
        i += workers;
    }
}

int16_t ECOCALLMETHOD lab_bitonic_sort(IEcoLab64* me, void* base, uint32_t count, uint32_t width, BitonicCompare compare, uint32_t workers, BitonicExecutor executor, void* executor_context, BitonicStats* stats) {
    uint32_t i;
    uint32_t N = 1;
    uint32_t stages = 0;
    uint64_t network_pairs = 0;
    uint32_t* indices = 0;
    uint32_t* temp = 0;
    void* output = 0;
    int16_t result = 0;

    if (!me || !compare || !base || !width || !executor) {
        return -1;
    }

    if (count > 1048576) {
        return -1;
    }

    if ((uint64_t)count * width > UINT32_MAX) {
        return -1;
    }

    if (count <= 1) {
        stats->padded_count = count;
        stats->stages = 0;
        stats->network_pairs = 0;
        return 0;
    }

    while (N < count) {
        N <<= 1;
    }

    IEcoMemoryAllocator1* allocator = lab_allocator(me);
    if (!allocator) {
        return -2;
    }

    indices = (uint32_t*)allocator->pVTbl->Alloc(allocator, N * sizeof(uint32_t));
    if (!indices) {
        return -2;
    }

    temp = (uint32_t*)allocator->pVTbl->Alloc(allocator, N * sizeof(uint32_t));
    if (!temp) {
        allocator->pVTbl->Free(allocator, indices);
        return -2;
    }

    for (i = 0; i < count; i++) {
        indices[i] = i;
    }

    for (i = count; i < N; i++) {
        indices[i] = count;
    }

    uint32_t k = 2;
    while (k <= N) {
        uint32_t j = k >> 1;
        while (j >= 1) {
            struct {
                uint32_t* indices;
                uint32_t* base;
                uint32_t width;
                uint32_t count;
                BitonicCompare compare;
                uint32_t k;
                uint32_t j;
            } context;

            context.indices = indices;
            context.base = (uint32_t*)base;
            context.width = width;
            context.count = N;
            context.compare = compare;
            context.k = k;
            context.j = j;

            if (workers == 1) {
                stage_job(&context, 0, 1);
            } else {
                int16_t exec_result = executor(executor_context, stage_job, &context, workers);
                if (exec_result != 0) {
                    allocator->pVTbl->Free(allocator, temp);
                    allocator->pVTbl->Free(allocator, indices);
                    return -3;
                }
            }

            j >>= 1;
            network_pairs += N / 2;
        }
        k <<= 1;
        k = k > N ? N : k;
        stages++;
    }

    output = allocator->pVTbl->Alloc(allocator, count * width);
    if (!output) {
        allocator->pVTbl->Free(allocator, temp);
        allocator->pVTbl->Free(allocator, indices);
        return -2;
    }

    for (i = 0; i < count; i++) {
        uint32_t src_idx = indices[i];
        allocator->pVTbl->Copy(allocator, (char*)output + i * width, (char*)base + src_idx * width, width);
    }

    allocator->pVTbl->Copy(allocator, base, output, count * width);
    allocator->pVTbl->Free(allocator, temp);
    allocator->pVTbl->Free(allocator, indices);
    allocator->pVTbl->Free(allocator, output);

    stats->padded_count = N;
    stats->stages = stages;
    stats->network_pairs = network_pairs;

    return 0;
}

#include "ArpoMethods.h"
#include "IEcoLab64.h"
#include "IEcoMemoryAllocator1.h"
